from contextlib import contextmanager
from typing import Generator, Union

from sglang.srt.debug_utils.comparator.output_types import ErrorLog, InfoLog

AnyLog = Union[ErrorLog, InfoLog]


class LogSink:
    """Collects :class:`ErrorLog` and :class:`InfoLog` entries.

    Replaces the old ``WarningSink``. Entries added inside a :meth:`context`
    are captured in a list; entries added outside a context are emitted to the
    active output (text or JSON) as a ``LogRecord``.
    """

    def __init__(self) -> None:
        self._stack: list[list[AnyLog]] = []

    @contextmanager
    def context(self) -> Generator[list[AnyLog], None, None]:
        bucket: list[AnyLog] = []
        self._stack.append(bucket)
        try:
            yield bucket
        finally:
            popped = self._stack.pop()
            assert popped is bucket

    def add(self, item: AnyLog) -> None:
        if self._stack:
            self._stack[-1].append(item)
        else:
            from sglang.srt.debug_utils.comparator.output_types import (
                LogRecord,
                _split_logs,
                report_sink,
            )

            errors, infos = _split_logs([item])
            report_sink.add(LogRecord(errors=errors, infos=infos))


log_sink = LogSink()
